# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">FUSSİLET SURESİ (1-54. AYETLER) TİLAVET VE TECVİT REHBERİ</text>\n  <rect x="20" y="44" width="210" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">1. Surenin Kimliği ve Mukattaa</text>\n  <rect x="35" y="78" width="180" height="36" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="125" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Mekkî Sure · 54 Ayet · 41. Sure</text>\n  <text x="32" y="132" font-size="10" fill="#334155">• <tspan font-weight="bold">1. Ayet (Hâ-Mîm):</tspan> Havâmîm</text>\n  <text x="40" y="147" font-size="10" fill="#334155">surelerinin ikincisidir.</text>\n  <text x="32" y="168" font-size="10" fill="#334155">• <tspan font-weight="bold">Hâ:</tspan> Medd-i Tabiî (1 Elif)</text>\n  <text x="32" y="186" font-size="10" fill="#334155">• <tspan font-weight="bold">Mîm:</tspan> Medd-i Lâzım Harfî (4 Elif)</text>\n  <text x="32" y="206" font-size="10" fill="#334155">• <tspan font-weight="bold">Adı:</tspan> 3. ayetteki "Fussilet"</text>\n  <text x="40" y="221" font-size="10" fill="#334155">(ayrıntılı açıklandı) lafzından gelir.</text>\n\n  <rect x="245" y="44" width="210" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">2. Özel Kıraat: Teshîl (44. Ayet)</text>\n  <rect x="260" y="78" width="180" height="36" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="350" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">e-a\'cemiyyun ve arabiyy</text>\n  <text x="257" y="132" font-size="10" fill="#334155">• Yan yana gelen iki fethalı</text>\n  <text x="265" y="147" font-size="10" fill="#334155">hemzeden ikincisi yumuşatılır.</text>\n  <text x="257" y="168" font-size="10" fill="#334155">• İkinci hemze, hemze ile elif</text>\n  <text x="265" y="183" font-size="10" fill="#334155">arasında yumuşak sesle okunur.</text>\n  <text x="257" y="204" font-size="10" font-weight="bold" fill="#92400e">• Hafs rivayetinde tek teshîl</text>\n  <text x="265" y="219" font-size="10" font-weight="bold" fill="#92400e">örneği Fussilet 44. ayettedir.</text>\n\n  <rect x="470" y="44" width="210" height="194" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">3. Tilavet ve Vakıf İlkeleri</text>\n  <rect x="485" y="78" width="180" height="36" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="575" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Tertîl ve Secavend Uyumu</text>\n  <text x="482" y="132" font-size="10" fill="#334155">• Tenvin ve sakin nûn kuralları</text>\n  <text x="490" y="147" font-size="10" fill="#334155">(izhar, ihfa, idgam) tam yapılır.</text>\n  <text x="482" y="168" font-size="10" fill="#334155">• 37-38. ayetlerde secde ayeti</text>\n  <text x="490" y="183" font-size="10" fill="#334155">işaretine dikkat edilir.</text>\n  <text x="482" y="204" font-size="10" fill="#334155">• Ayet sonlarında kalkale ve</text>\n  <text x="490" y="219" font-size="10" fill="#334155">medd-i ârız kuralları uygulanır.</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">FUSSİLET SURESİ 37-38. AYETLER VE TİLAVET SECDESİ UYGULAMASI</text>\n  <rect x="20" y="42" width="660" height="44" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="61" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Fussilet 37. Ayet Mesajı: "Güneşe ve aya secde etmeyin; onları yaratan Allah\'a secde edin!"</text>\n  <text x="350" y="78" text-anchor="middle" font-size="10.5" fill="#334155">Kur\'an-ı Kerim\'de yer alan 14 secde ayetinden biri Fussilet suresi 37-38. ayetlerindedir.</text>\n\n  <rect x="20" y="100" width="156" height="138" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="98" y="122" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. Hazırlık ve Niyet</text>\n  <text x="30" y="146" font-size="10" fill="#334155">• Abdestli olunur ve</text>\n  <text x="36" y="161" font-size="10" fill="#334155">kıbleye yönelinir.</text>\n  <text x="30" y="182" font-size="10" fill="#334155">• Allah rızası için</text>\n  <text x="36" y="197" font-size="10" fill="#334155">tilavet secdesi</text>\n  <text x="36" y="212" font-size="10" fill="#334155">yapmaya niyet edilir.</text>\n\n  <rect x="188" y="100" width="156" height="138" rx="8" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="266" y="122" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#5b21b6">2. Tekbirle Secde</text>\n  <text x="198" y="146" font-size="10" fill="#334155">• Eller kulak hizasına</text>\n  <text x="204" y="161" font-size="10" fill="#334155">kaldırılmaz.</text>\n  <text x="198" y="182" font-size="10" fill="#334155">• Rükû yapılmadan</text>\n  <text x="204" y="197" font-size="10" font-weight="bold" fill="#5b21b6">"Allâhü ekber"</text>\n  <text x="204" y="212" font-size="10" fill="#334155">diyerek secdeye inilir.</text>\n\n  <rect x="356" y="100" width="156" height="138" rx="8" fill="#fce7f3" stroke="#db2777" stroke-width="2"/>\n  <text x="434" y="122" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9d174d">3. Secde Tesbihi</text>\n  <text x="366" y="146" font-size="10" fill="#334155">• Tek bir secde yapılır.</text>\n  <text x="366" y="166" font-size="10" fill="#334155">• Secdede üç defa:</text>\n  <text x="434" y="188" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#9d174d">"Sübhâne Rabbiye\'l-a\'lâ"</text>\n  <text x="366" y="210" font-size="9.5" fill="#334155">(Yüce Rabbimi eksiklikten</text>\n  <text x="366" y="224" font-size="9.5" fill="#334155">tenzih ederim) denir.</text>\n\n  <rect x="524" y="100" width="156" height="138" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="602" y="122" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">4. Kalkış ve Dua</text>\n  <text x="534" y="146" font-size="10" fill="#334155">• "Allâhü ekber" diyerek</text>\n  <text x="540" y="161" font-size="10" fill="#334155">secdeden kalkılır.</text>\n  <text x="534" y="182" font-size="10" fill="#334155">• Selam verilmez;</text>\n  <text x="602" y="202" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">"Gufrâneke Rabbenâ</text>\n  <text x="602" y="218" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">ve ileyke\'l-masîr" okunur.</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">FUSSİLET SURESİ 33-53. AYETLER: DAVET AHLAKI VE KEVNÎ DELİLLER</text>\n  <rect x="20" y="44" width="320" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">1. En Güzel Söz ve İyilik Ahlakı (33-35. Ayetler)</text>\n  <rect x="34" y="78" width="292" height="32" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="180" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Ahsenü\'l-Kavl = Davet + Salih Amel + İslam Kimliği</text>\n  <text x="34" y="130" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#15803d">İlke (34. Ayet):</tspan> İyilik (hasene) ile kötülük</text>\n  <text x="42" y="145" font-size="10" fill="#475569">(seyyie) eşit değildir; kötülüğü en güzel tavırla sav.</text>\n  <text x="34" y="168" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#15803d">Meyvesi:</tspan> Arada düşmanlık bulunan kimsenin</text>\n  <text x="42" y="183" font-size="10" fill="#475569">samimi bir dosta (Veliyyün Hamîm) dönüşmesi.</text>\n  <text x="34" y="206" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#15803d">Şartı (35. Ayet):</tspan> Sabır ve yüksek ahlaki olgunluk.</text>\n\n  <rect x="360" y="44" width="320" height="194" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">2. Âfâkî ve Enfüsî Deliller (53-54. Ayetler)</text>\n  <rect x="374" y="78" width="292" height="32" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="520" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Senürîhim Âyâtinâ fi\'l-Âfâkı ve fî Enfüsihim</text>\n  <text x="374" y="130" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#1d4ed8">Âfâkî Deliller (Ufuklar / Dış Dünya):</tspan> Göklerin,</text>\n  <text x="382" y="145" font-size="10" fill="#475569">yerin, gezegenlerin ve doğa yasalarının düzeni.</text>\n  <text x="374" y="168" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#1d4ed8">Enfüsî Deliller (Nefisler / İç Dünya):</tspan> İnsanın</text>\n  <text x="382" y="183" font-size="10" fill="#475569">bedenindeki organların, hücrelerin ve ruhunun yapısı.</text>\n  <text x="374" y="206" font-size="10.5" fill="#334155">• <tspan font-weight="bold" fill="#1d4ed8">Gaye:</tspan> Kur\'an\'ın hak olduğunun apaçık bilinmesi.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
